pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        bool ok;
        try c.setL1BlockValues(42, 100, 200, keccak256("test"), 1, bytes32(0), 1000, 2000) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
